class NewValueTableDialog(QDialog):

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("New Value Table")
        self.resize(420, 300)

        root = QVBoxLayout(self)
        root.setContentsMargins(14, 12, 14, 12)
        root.setSpacing(8)

        name_row = QHBoxLayout()
        name_row.addWidget(QLabel("Name:"))
        self.name_edit = QLineEdit()
        name_row.addWidget(self.name_edit, 1)
        root.addLayout(name_row)

        self.table = QTableWidget(0, 2)
        self.table.setHorizontalHeaderLabels(["Value", "Description"])
        self.table.horizontalHeader().setStretchLastSection(True)
        root.addWidget(self.table, 1)

        table_buttons = QHBoxLayout()
        add_button = QPushButton("Add")
        delete_button = QPushButton("Delete")
        add_button.clicked.connect(self.add_row)
        delete_button.clicked.connect(self.delete_row)
        table_buttons.addWidget(add_button)
        table_buttons.addWidget(delete_button)
        table_buttons.addStretch()
        root.addLayout(table_buttons)

        buttons = QHBoxLayout()
        buttons.addStretch()
        ok_button = QPushButton("OK")
        cancel_button = QPushButton("Cancel")
        ok_button.clicked.connect(self.accept)
        cancel_button.clicked.connect(self.reject)
        buttons.addWidget(ok_button)
        buttons.addWidget(cancel_button)
        root.addLayout(buttons)

    def add_row(self):
        row = self.table.rowCount()
        self.table.insertRow(row)
        self.table.setItem(row, 0, QTableWidgetItem(""))
        self.table.setItem(row, 1, QTableWidgetItem(""))
        self.table.setCurrentCell(row, 0)

    def delete_row(self):
        row = self.table.currentRow()
        if row >= 0:
            self.table.removeRow(row)

    def get_data(self):
        choices = {}
        for row in range(self.table.rowCount()):
            value_item = self.table.item(row, 0)
            description_item = self.table.item(row, 1)
            if value_item is None:
                continue
            value_text = value_item.text().strip()
            description = description_item.text().strip() if description_item else ""
            if not value_text:
                continue
            try:
                value = int(value_text)
            except ValueError:
                continue
            choices[value] = description
        return self.name_edit.text().strip(), choices


